-- C-104 : bulletin complet du primaire privé (modèle B). Nouvelle version (dernière version + 1, l'ancienne reste pour les documents déjà émis) des
-- modèles de la plateforme : tableau détaillé par matière (séquences SEQ, MOY, COEF, TOTAL, RANG), totaux par domaine, profil de la classe, bloc
-- Travail (distinctions selon les seuils paramétrés de l'école), date de naissance et matricule. Une donnée absente n'est pas affichée (colonnes et
-- lignes n'existent que si la donnée existe). Les anciennes variables restent déclarées (modèles personnalisés). Idempotent.

UPDATE document_types SET variables = REPLACE(variables, ']', ',"identity_line","subjects_detail_table","domain_totals_table","class_profile_table","work_table"]'), updated_at = '2026-11-05T13:02:00+01:00' WHERE tenant_id = '*' AND code = 'pri_report_card' AND variables NOT LIKE '%"subjects_detail_table"%';
UPDATE document_types SET variables = REPLACE(variables, ']', ',"identity_line"]'), updated_at = '2026-11-05T13:02:00+01:00' WHERE tenant_id = '*' AND code = 'pri_annual_report' AND variables NOT LIKE '%"identity_line"%';

INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) SELECT '01C104RC00F000000000000000', tenant_id, establishment_id, type_code, locale, REPLACE(REPLACE(html, '<td>{{repeater}}</td>', '<td>{{repeater}} {{identity_line}}</td>'), '<table class="lay"><tr><td width="38%">{{table:subjects_table}}</td><td class="gap"></td><td>{{table:competencies_table}}</td></tr></table>', '<table class="lay"><tr><td width="58%">{{table:subjects_detail_table}}{{table:domain_totals_table}}</td><td class="gap"></td><td>{{table:competencies_table}}{{table:class_profile_table}}{{table:work_table}}</td></tr></table>'), version + 1, '2026-11-05T13:02:00+01:00', NULL, '2026-11-05T13:02:00+01:00' FROM document_templates WHERE tenant_id = '*' AND establishment_id = '' AND type_code = 'pri_report_card' AND locale = 'fr' AND html LIKE '%{{table:subjects_table}}%' AND html NOT LIKE '%subjects_detail_table%' AND version = (SELECT MAX(t.version) FROM document_templates t WHERE t.tenant_id = '*' AND t.establishment_id = '' AND t.type_code = 'pri_report_card' AND t.locale = 'fr');
